changeSet.sql:

DO $BLOCK$ 
DECLARE 
    prev_version_exists integer;
    new_version_exists integer;
BEGIN
    SELECT COUNT(*) INTO prev_version_exists 
    FROM ${currency.table} 
    WHERE deployment_version = '${prev.version.number}';

    IF prev_version_exists = 0 THEN
        RAISE EXCEPTION 'Previous version % does not exist', '${prev.version.number}';
    END IF;

    SELECT COUNT(*) INTO new_version_exists 
    FROM ${currency.table} 
    WHERE deployment_version = '${version.number}';

    IF new_version_exists > 0 THEN
        RAISE EXCEPTION 'Version % already exists', '${version.number}';
    END IF;

    IF ${version.number}::integer <= ${prev.version.number}::integer THEN
        RAISE EXCEPTION 'New version must be greater than previous version';
    END IF;
END $BLOCK$;
